36	blog_post	3	13	Exception as e:\n print(f"Ошибка копирования: {e}")\n return None\n \n \n [](<https://sourcecraft.dev/>)\n\n#### Преобразование форматирования\n\nTelegram использует собственный формат для текста с сущностями. Необходимо преобразовать его в Markdown.\n \n \n def parse_text_entities(self, text: Union[str, List], entities: Optional[List[Dict]] = None) -> str:\n if isinstance(text, str) and ('<' in text or '&' in text):\n return self.html_to_markdown(text)\n \n if entities is not None and isinstance(entities, list) and isinstance(text, str):\n return self._process_entities(text, entities)\n \n if isinstance(text, list):\n return self._process_text_list(text)\n \n return str(text) if text else ""\n \n def _process_single_entity(self, text: str, entity_type: str, entity: Dict) -> str:\n handlers = {\n 'bold': lambda t:	{"tags": ["telegram", "obsidian", "python", "knowledge-base", "llm"], "title": "Конвертация экспорта Telegram в Obsidian: руководство по созданию личной базы знаний"}	2026-11-21 16:31:45.779569+00	2026-11-21 16:31:45.779569+00	[-0.030578205,-0.021317065,0.050488744,-0.0040026577,-0.015764033,-0.024769442,0.0014693156,0.005895529,-0.01985574,-0.0019191294,-0.011973724,-0.013480714,0.0053840657,-0.0125582535,0.009160675,-0.022321723,0.0207508,0.02970141,0.018093018,-0.016101964,-0.026486497,0.009165241,-0.027381558,0.013681646,-0.002979731,0.009781738,-0.00047464488,-0.03235006,0.015435235,-0.011224795,0.018312216,0.016293762,0.024550244,-0.041647736,-0.021700662,-0.0054845316,0.0033427787,0.0015126987,-0.02272359,0.0104393335,-0.0010914264,0.03627737,0.009220041,-0.07964216,0.0369167,-0.006881923,0.04562984,-0.029792743,-0.015480901,-0.022157324,-0.031692464,0.0019625125,0.026815295,0.016275495,0.0027057328,0.03516311,0.012841385,-0.018887613,-0.028550617,0.041684266,-0.014832439,-0.015773166,0.038615488,0.027911289,-0.00021620175,0.039967213,0.020038405,0.033774853,0.0023952015,-0.039053883,0.0013951077,0.06385986,0.005142034,-0.024915574