90	blog_post	2	39	тивную память\n del new_dataset\n # ПРОСМОТР ЧЕРЕЗ ArcGis или QGIS\n \n \n [](<https://sourcecraft.dev/>)\n\nИзвлекаем из полученного растра видимый красный и IR и рассчитываем индекс NDVI.\n \n \n landsat_ds = gdal.Open(workdir + r".\\Lansat-8_2021_05_16\\Composit_bands_1_7.tif")\n # Извлешем из многоканального растра видимый красный и ближний ИК каналы\n red_band_array = landsat_ds.GetRasterBand(4).ReadAsArray()\n nir_band_array = landsat_ds.GetRasterBand(5).ReadAsArray()\n \n [](<https://sourcecraft.dev/>)\n \n \n # Расчет индекса растительности NDVI\n ndvi_array = (nir_band_array - red_band_array) / (nir_band_array + red_band_array)\n # Нормируем к единице\n ndvi_array_norm = ndvi_array / numpy.nanmax(ndvi_array)\n plt.close()\n plt.imshow(ndvi_array_norm)\n plt.colorbar()\n plt.show()\n \n [](<https://sourcecraft	{"tags": ["gis", "gdal", "landsat", "numpy", "spectral-indexes"], "title": "Получение, обработка, анализ и визуализация спутниковых снимков с помощью библиотек: GDAL, numpy и matplotlib"}	2026-11-21 16:31:51.535472+00	2026-11-21 16:31:51.535472+00	[-0.07533365,-0.008681243,0.0009542386,0.017269392,-0.027835838,-0.010287157,0.010166132,0.048037767,0.017679015,0.019196488,-0.042042356,-0.01966197,-0.014038945,0.08147801,0.044202194,-0.023441685,-0.008592802,-0.006297975,0.0392867,-0.030517016,0.020872224,0.018814793,-0.02539671,0.05980516,-0.0078014825,0.004463975,0.038132306,-0.048894253,0.0854253,0.05731017,0.0013964467,-0.047777098,0.048559107,-0.027705504,-0.037108243,0.0069822334,-0.014960599,-0.021896284,-0.044016,0.015910182,0.00268816,0.029139187,0.010910904,-0.016403593,0.052618112,-0.04427667,0.0069077564,-0.05764532,-0.03857917,-0.042079594,-0.036065564,-0.011460173,0.026160102,-0.027724123,-0.050979614,0.04245198,-0.0061769495,-0.0033002691,-0.034892548,0.006372452,0.004561726,0.0050178985,-0.05112857,-0.014234447,0.024000265,0.01649669,0.025173279,0.012102538,-0.004328985,-0.00029907233,-0.02148666,0.050495513,-0.052059535,