133	blog_post	1	37	ю в своем заголовке, разрешающую его выполнение, защищающую приложение от внешних атак – CSRF-токен. По умолчанию CSRF-токен хранится в cookie и для его включения в заголовок запроса его необходимо извлечь следующей функцией.\n \n \n // Функция получения CSRF-токен (он нужен для POST-запрооса) из куки \n function getCookie(name) {\n var cookieValue = null;\n if (document.cookie && document.cookie !== '') {\n var cookies = document.cookie.split(';');\n for (var i = 0; i < cookies.length; i++) {\n var cookie = cookies[i].trim();\n // Проверяем, начинается ли куки с искомого имени\n if (cookie.substring(0, name.length + 1) === (name + '=')) {\n // Извлекаем значение куки\n cookieValue = decodeURIComponent(cookie.substring(name.length + 1));\n break;\n }\n }\n }\n return cookieValue;\n }\n \n // Получаем CSRF-токен из куки (Это вынесено во внутрь post-запроса)\n var csrftoken = getCookie('csrftoken');\n \n [](<https://sourcecraft.dev/>)	{"tags": ["geodjango", "postgis", "web-gis", "django", "arrow"], "title": "Практика реализации Веб-ГИС приложений и сервисов на основе открытых ресурсов. Начало"}	2026-11-21 16:31:55.930317+00	2026-11-21 16:31:55.930317+00	[-0.03212787,0.016036874,0.008771575,-0.031658847,-0.0093623595,0.013493343,0.022783546,0.007283339,-0.017849816,-0.003483826,-2.7305474e-05,0.0020294134,-0.053396117,-0.0041084345,-0.0046135327,0.0062821615,0.016298443,0.008460399,0.0036123556,-0.014314128,-0.015549815,0.031442378,-0.044809446,-0.009461575,0.040732577,-0.015991777,0.005267455,-0.035483163,-0.0039641205,-0.015955698,0.034346692,0.034509044,0.02197178,-0.02081727,-0.010156086,-0.011815695,-0.03817101,-0.0024262762,-0.02736551,0.0074727507,-0.010183144,0.056065924,0.034743555,-0.05541651,0.028032962,-0.03277728,0.012041185,-0.019464327,-0.01520707,0.0078019663,-0.049463566,-0.011653342,0.015802365,-0.050401606,0.0022346096,0.038748264,0.012104322,-0.031983554,-0.03349885,-0.010850596,-0.013872167,-0.01543256,-0.056029845,0.016623149,-0